package com.ias.finance;

import com.ias.trust.*;
import jakarta.servlet.http.*;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;
import javax.sql.DataSource;
import java.time.Instant;
import java.util.*;

@RestController
public final class MoneyNotificationContextController {
 private static final Set<String> BASE=Set.of("eventId","eventType","schemaVersion","tenantId","companyId","groupId","billId","completionId","accountVersion","action","businessId","amountCents","authorityDigest","executionReceiptsDigest","originalPaymentId","occurredAt","purpose");
 private final JdbcTemplate db;
 public MoneyNotificationContextController(DataSource source){db=new JdbcTemplate(source);}
 @PostMapping("/internal/finance/money-notification-context")Map<String,Object> context(@RequestBody Map<String,Object>b,HttpServletRequest r){
  edge(r);String purpose=text(b,"purpose");var expected=new HashSet<>(BASE);if("READ".equals(purpose))expected.add("sessionToken");if(!Set.of("DELIVERY","READ").contains(purpose)||!b.keySet().equals(expected)||!"1".equals(b.get("schemaVersion")))throw bad();
  String tenant=positive(b,"tenantId"),company=positive(b,"companyId"),account=positive(b,"accountVersion"),eventType=text(b,"eventType");if(!Set.of("finance.collection_finalized","finance.refund_finalized").contains(eventType))throw bad();
  String event=uuid(b,"eventId"),group=uuid(b,"groupId"),bill=uuid(b,"billId"),completion=uuid(b,"completionId"),business=uuid(b,"businessId"),amount=nonnegative(b,"amountCents"),occurred=text(b,"occurredAt");uuidNullable(b,"originalPaymentId");hex(b,"authorityDigest");hex(b,"executionReceiptsDigest");Instant.parse(occurred);
  var rows=db.queryForList("SELECT t.*,o.event_id,o.event_type,o.payload_json,g.row_version current_group_version,g.customer_company_id current_company,a.row_version current_account_version FROM finance_money_terminal_fact t JOIN finance_outbox o ON o.tenant_id=t.tenant_id AND o.operation_id=t.operation_id JOIN finance_fee_group g ON g.tenant_id=t.tenant_id AND g.fault_group_id=t.fault_group_id JOIN finance_money_account a ON a.tenant_id=t.tenant_id AND a.fault_group_id=t.fault_group_id WHERE o.event_id=? AND t.tenant_id=?",event,Long.parseLong(tenant));if(rows.size()!=1)throw new Problem(404,"MONEY_NOTIFICATION_FACT_NOT_FOUND");var row=rows.getFirst();
  exact(row,"customer_company_id",company);exact(row,"fault_group_id",group);exact(row,"bill_id",bill);exact(row,"completion_id",completion);exact(row,"account_version",account);exact(row,"action_name",text(b,"action"));exact(row,"business_id",business);exact(row,"amount_cents",amount);exact(row,"authority_digest",text(b,"authorityDigest"));exact(row,"execution_receipts_digest",text(b,"executionReceiptsDigest"));exactNullable(row,"original_payment_id",b.get("originalPaymentId"));if(!wire(row.get("terminal_event_type")).equals(eventType))throw new Problem(409,"MONEY_NOTIFICATION_FACT_STALE");Map<String,Object> payload;try{payload=FinanceController.JSON.readValue(row.get("terminal_payload_json").toString(),Map.class);}catch(Exception e){throw new Problem(503,"MONEY_NOTIFICATION_FACT_INVALID");}for(String key:List.of("schemaVersion","tenantId","companyId","groupId","billId","completionId","accountVersion","action","businessId","amountCents","authorityDigest","executionReceiptsDigest","originalPaymentId","occurredAt"))if(!Objects.equals(payload.get(key),b.get(key)))throw new Problem(409,"MONEY_NOTIFICATION_FACT_STALE");
  if(row.get("department_id")==null||row.get("applicant_user_id")==null)throw new Problem(503,"MONEY_NOTIFICATION_OWNER_MISSING");boolean current=company.equals(row.get("current_company").toString())&&((Number)row.get("current_account_version")).longValue()>=Long.parseLong(account);if(!current)throw new Problem(409,"MONEY_NOTIFICATION_SCOPE_REVOKED");if("READ".equals(purpose))read(r,text(b,"sessionToken"),tenant,company);
  var out=new LinkedHashMap<String,Object>();for(String key:BASE)if(!key.equals("purpose"))out.put(key,b.get(key));out.put("departmentId",row.get("department_id").toString());out.put("applicantUserId",row.get("applicant_user_id").toString());out.put("factVersion",account);out.put("eventVersion",row.get("terminal_event_version"));out.put("currentScope",true);out.put("qualified",true);out.put("revoked",false);out.put("checkedAt",Instant.now().toString());return out;
 }
 private void read(HttpServletRequest r,String token,String tenant,String company){var f=Chain.call("finance-identity","/internal/identity/domain-authorizations",Map.of("sessionToken",token,"purpose","MONEY_READ"),Chain.trace(r),Chain.deadline(r));Chain.fresh(f,Chain.deadline(r));if(!Boolean.TRUE.equals(f.get("enabled"))||!tenant.equals(f.get("tenantId"))||!((List<?>)f.getOrDefault("permissions",List.of())).contains("finance.money.read")||!((List<?>)f.getOrDefault("companyIds",List.of())).contains(company))throw new Problem(403,"ACCESS_DENIED");}
 private static String wire(Object value){return switch(Objects.toString(value,"")){case "FINANCE_COLLECTION_FINALIZED"->"finance.collection_finalized";case "FINANCE_REFUND_FINALIZED"->"finance.refund_finalized";default->throw new Problem(503,"MONEY_NOTIFICATION_FACT_INVALID");};}
 private static void edge(HttpServletRequest r){if(!Chain.active()||!"finance".equals(Chain.role())||!r.isSecure()||!"notification-finance".equals(r.getAttribute("ias.chain.edge")))throw new Problem(403,"SERVICE_AUTHENTICATION_FAILED");}
 private static void exact(Map<String,Object>r,String k,String v){if(!v.equals(Objects.toString(r.get(k),"")))throw new Problem(409,"MONEY_NOTIFICATION_FACT_STALE");}
 private static void exactNullable(Map<String,Object>r,String k,Object v){if(!Objects.equals(r.get(k)==null?null:r.get(k).toString(),v))throw new Problem(409,"MONEY_NOTIFICATION_FACT_STALE");}
 private static String text(Map<String,Object>b,String k){if(!(b.get(k)instanceof String s)||s.isBlank())throw bad();return s;}private static String positive(Map<String,Object>b,String k){String s=text(b,k);if(!s.matches("[1-9][0-9]{0,18}"))throw bad();return s;}private static String nonnegative(Map<String,Object>b,String k){String s=text(b,k);if(!s.matches("0|[1-9][0-9]{0,18}"))throw bad();return s;}private static String uuid(Map<String,Object>b,String k){String s=text(b,k);try{if(!UUID.fromString(s).toString().equals(s))throw bad();return s;}catch(Exception e){throw bad();}}private static void uuidNullable(Map<String,Object>b,String k){if(b.get(k)==null)return;uuid(b,k);}private static void hex(Map<String,Object>b,String k){if(!text(b,k).matches("[a-f0-9]{64}"))throw bad();}private static Problem bad(){return new Problem(400,"INVALID_REQUEST");}
 @ExceptionHandler(Problem.class)ResponseEntity<Map<String,Object>> problem(Problem p){return ResponseEntity.status(p.status).header("Cache-Control","no-store").body(Map.of("code",p.code,"retryable",p.status==503));}
 @ExceptionHandler(Exception.class)ResponseEntity<Map<String,Object>> unknown(Exception e){return problem(new Problem(503,"DEPENDENCY_UNAVAILABLE"));}
}
